import ts from 'typescript';
import MagicString from 'magic-string';

export interface ComponentCompilation {
  component: string;
  status: 'compiled' | 'fallback';
  reason?: string;
  nodes?: number;
  bindings?: number;
  events?: number;
  holes?: number;
}
export interface CompilationResult {
  code: string;
  map: ReturnType<MagicString['generateMap']>;
  components: ComponentCompilation[];
  optimizedLists: number;
}

// Deliberately excludes native elements with special mounting semantics:
// dialog, select, form controls, SVG, raw HTML and structural nodes.
const tags = new Set([
  'div',
  'span',
  'p',
  'section',
  'article',
  'header',
  'footer',
  'main',
  'aside',
  'nav',
  'strong',
  'em',
  'small',
  'b',
  'i',
  'ul',
  'ol',
  'li',
  'table',
  'thead',
  'tbody',
  'tr',
  'td',
  'th',
  'button',
  'label',
  'h1',
  'h2',
  'h3',
  'h4',
  'h5',
  'h6',
]);
// The renderer's event names (EVENT_NAMES in the interpreter).
const events = new Set([
  'abort',
  'blur',
  'change',
  'click',
  'contextmenu',
  'dblclick',
  'error',
  'focus',
  'input',
  'keydown',
  'keypress',
  'keyup',
  'load',
  'mousedown',
  'mouseenter',
  'mouseleave',
  'mousemove',
  'mouseout',
  'mouseover',
  'mouseup',
  'paste',
  'pointerdown',
  'pointerenter',
  'pointerleave',
  'pointermove',
  'pointerup',
  'reset',
  'scroll',
  'submit',
  'touchend',
  'touchmove',
  'touchstart',
