await writeFile(
  join(output, 'provenance.json'),
  JSON.stringify(
    {
      baseCommit,
      ids,
      runs: process.env.PAGE_RUNS,
      iterations: process.env.PAGE_ITERATIONS,
      scales: process.env.PAGE_SCALES,
      cpu: cpus()[0].model,
      platform: platform(),
      release: release(),
      node: process.version,
      runnerSha256: hash(runner),
      runnerSource: runner,
      builds,
    },
    null,
    2,
  ) + '\n',
);

